#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *score = malloc(sizeof *score);
    if (score == NULL) {
        fputs("could not allocate score\n", stderr);
        return 1;
    }

    *score = 86;
    printf("score=%d\n", *score);

    free(score);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t count = 4;
    int *values = malloc(count * sizeof *values);
    if (values == NULL) {
        fputs("could not allocate array\n", stderr);
        return 1;
    }

    for (size_t i = 0; i < count; ++i) {
        values[i] = (int)(i + 1) * 10;
    }

    for (size_t i = 0; i < count; ++i) {
        printf("%d%c", values[i], i + 1 == count ? '\n' : ' ');
    }

    free(values);
    return 0;
}
